    void sharedComposerSupportsMultilineResizeAndExpansion() {
        SessionController controller;MainWindow w(&controller);w.show();auto* input=get<QPlainTextEdit>(w,"sendInput");auto* split=get<QSplitter>(w,"workspaceSplitter");auto* expand=get<QToolButton>(w,"expandComposer");
        const QString content=QStringLiteral("{\n  \"device\": \"sensor\",\n  \"operation\": \"query\",\n  \"values\": [1, 2, 3],\n  \"enabled\": true\n}\n");
        for(const auto& size:{QSize(1440,1000),QSize(1100,760)}){
            w.resize(size);QTest::qWait(40);QCOMPARE(w.size(),size);
            for(int kind=0;kind<4;++kind){get<QListWidget>(w,"profileList")->setCurrentRow(kind);get<QComboBox>(w,"sendFormat")->setCurrentIndex(1);input->setPlainText(content);QTest::qWait(30);
                QVERIFY(input->height()>=96);QVERIFY(input->width()>get<QWidget>(w,"composer")->width()*0.85);QVERIFY(get<QWidget>(w,"sendSettings")->mapTo(&w,QPoint()).y()>input->mapTo(&w,QPoint()).y()+input->height());
                for(QWidget* control:std::initializer_list<QWidget*>{input,get<QPushButton>(w,"sendButton"),get<QComboBox>(w,"sendFormat"),get<QComboBox>(w,"sendEncoding"),get<QSpinBox>(w,"periodicInterval"),get<QSpinBox>(w,"periodicCount"),expand})for(auto* parent=control->parentWidget();parent&&parent!=&w;parent=parent->parentWidget())QVERIFY2(parent->rect().contains(QRect(control->mapTo(parent,QPoint()),control->size())),qPrintable(control->objectName()+" clipped by "+parent->objectName()));
                const auto sizes=split->sizes();const int normalHeight=input->height();expand->click();QTest::qWait(30);qInfo("Composer protocol=%d window=%dx%d default=%dx%d expanded=%dx%d",kind,w.width(),w.height(),input->width(),normalHeight,input->width(),input->height());QVERIFY(input->height()>normalHeight+70);QCOMPARE(input->toPlainText(),content);QVERIFY(input->hasFocus());QVERIFY(!controller.connected());QCOMPARE(controller.statistics().txBytes,std::uint64_t(0));screenshot(w,QStringLiteral("composer-expanded-%1-%2x%3.png").arg(kind).arg(size.width()).arg(size.height()));expand->click();QTest::qWait(30);QVERIFY(std::abs(split->sizes()[0]-sizes[0])<=2);QCOMPARE(input->toPlainText(),content);
            }
            screenshot(w,QStringLiteral("composer-default-%1x%2.png").arg(size.width()).arg(size.height()));
        }
        w.resize(1440,1000);QTest::qWait(30);const int before=input->height();const QPoint handleCenter=split->handle(1)->rect().center();QTest::mousePress(split->handle(1),Qt::LeftButton,Qt::NoModifier,handleCenter);QTest::mouseMove(split->handle(1),handleCenter-QPoint(0,60));QTest::mouseRelease(split->handle(1),Qt::LeftButton,Qt::NoModifier,handleCenter-QPoint(0,60));QTest::qWait(30);QVERIFY(input->height()>before+30);QCOMPARE(input->toPlainText(),content);
        QUdpSocket peer;QVERIFY(peer.bind(QHostAddress::LocalHost,0));loopbackConfig(w,3);get<QSpinBox>(w,"remotePort")->setValue(peer.localPort());get<QPushButton>(w,"connectButton")->click();QTRY_VERIFY(controller.connected());get<QComboBox>(w,"sendFormat")->setCurrentIndex(1);input->setPlainText(content);expand->click();QTest::qWait(100);QVERIFY(!peer.hasPendingDatagrams());get<QPushButton>(w,"sendButton")->click();QTRY_VERIFY(peer.hasPendingDatagrams());QByteArray received(content.toUtf8().size(),'\0');QCOMPARE(peer.readDatagram(received.data(),received.size()),qint64(received.size()));QCOMPARE(received,content.toUtf8());expand->click();QVERIFY(controller.connected());QCOMPARE(input->toPlainText(),content);
        get<QPushButton>(w,"themeButton")->click();screenshot(w,"composer-multiline-light.png");
    }
