        {SessionController controller;MainWindow w(&controller);w.show();QTest::qWait(30);w.resize(1100,760);QTest::qWait(30);auto* split=get<QSplitter>(w,"workspaceSplitter");split->setSizes({180,260});QTest::qWait(30);saved=split->sizes();get<QToolButton>(w,"expandComposer")->click();QTest::qWait(30);QVERIFY(get<QToolButton>(w,"expandComposer")->isChecked());}
