        get<QPushButton>(w,"returnActiveProfile")->click();QCOMPARE(list->currentRow(),3);QTRY_VERIFY(!get<QPushButton>(w,"returnActiveProfile")->isVisible());QTRY_VERIFY(receiveRow(get<QTableView>(w,"recordTable"),4)>=0);QVERIFY(controller.recording());QCOMPARE(detailSessionTestAccess::generation(controller),generation);QVERIFY(picker->text().contains(QString::number(endpoint.port)));QVERIFY(!list->isVisible());QVERIFY(!peer.hasPendingDatagrams());QCOMPARE(w.size(),QSize(1100,760));screenshot(w,"profile-picker-active-dark.png");get<QPushButton>(w,"themeButton")->click();QCOMPARE(menu->property("darkTheme").toBool(),false);screenshot(w,"profile-picker-active-light.png");guard.start(2000);QTimer::singleShot(60,[&]{screenshot(*menu,"profile-picker-search-light.png");QTest::keyClick(search,Qt::Key_Escape);});QTest::mouseClick(picker,Qt::LeftButton);QVERIFY(!menu->isVisible());
