        QTimer guard;guard.setSingleShot(true);QObject::connect(&guard,&QTimer::timeout,menu,&QMenu::close);guard.start(2000);QTimer::singleShot(60,[&]{QVERIFY(menu->isVisible());QVERIFY(list->height()<=384);QVERIFY(list->verticalScrollBar()->maximum()>0);screenshot(*menu,"profile-picker-many.png");const int fullHeight=menu->height();search->setText(QStringLiteral("设备 29"));QVERIFY(menu->height()<fullHeight);int visible=0;for(int i=0;i<list->count();++i)visible+=!list->item(i)->isHidden();QCOMPARE(visible,1);QVERIFY(!list->item(29)->isHidden());QTest::keyClick(search,Qt::Key_Return);});QTest::mouseClick(picker,Qt::LeftButton);QCOMPARE(list->currentRow(),29);QVERIFY(!menu->isVisible());QVERIFY(!list->isVisible());QVERIFY(!controller.connected());QCOMPARE(controller.statistics().txBytes,std::uint64_t(0));QVERIFY(picker->toolTip().contains(QString::fromStdString(profiles[29].name)));screenshot(w,"profile-picker-long-name.png");
