        get<QPushButton>(w,"capturesNavigation")->click();QTRY_VERIFY(get<QListWidget>(w,"captureList")->count()>0);QVERIFY(!get<QPushButton>(w,"captureRowDelete0")->isEnabled());get<QPushButton>(w,"workspaceNavigation")->click();QVERIFY(controller.connected());get<QListWidget>(w,"profileList")->setCurrentRow(3);
        QTRY_VERIFY(receiveRow(table,10)>=0);QVERIFY(receiveRow(table,6)>=0);QCOMPARE(detailSessionTestAccess::generation(controller),generation);QCOMPARE(controller.localEndpoint().port,local.port);QVERIFY(controller.recording());
        QTRY_VERIFY(get<QPlainTextEdit>(w,"normalStreamView")->toPlainText().contains("while-away"));QVERIFY(get<QPlainTextEdit>(w,"normalStreamView")->toPlainText().contains("before"));
