        get<QListWidget>(w,"profileList")->setCurrentRow(1);window.reset();QVERIFY(!controller.connected());QVERIFY(!controller.recording());bool rebound=false;QTRY_VERIFY(rebound||(rebound=competing.bind(QHostAddress::LocalHost,local.port,QUdpSocket::DontShareAddress)));
