int main(int argc,char** argv) {
    // Windows offscreen uses FreeType rather than the normal native font loader.
    // Register real installed fonts so screenshot artifacts remain reviewable.
    if(qEnvironmentVariable("QT_QPA_PLATFORM")=="offscreen" && qEnvironmentVariableIsEmpty("QT_QPA_FONTDIR"))
        qputenv("QT_QPA_FONTDIR",(qEnvironmentVariable("WINDIR","C:/Windows")+"/Fonts").toUtf8());
    QApplication::setAttribute(Qt::AA_DontUseNativeDialogs);
    QApplication app(argc,argv);
    if(QGuiApplication::platformName()=="offscreen") {
        const auto fontDir=qEnvironmentVariable("WINDIR","C:/Windows")+"/Fonts/";
        for(const auto& file:{"segoeui.ttf","consola.ttf","msyh.ttc"})QFontDatabase::addApplicationFont(fontDir+QString::fromLatin1(file));
    }
    UiTest tests;return QTest::qExec(&tests,argc,argv);
}
